CREATE TABLE T_PERSON (ID INTEGER PRIMARY KEY, FIRST_NAME VARCHAR(100) NOT NULL, LAST_NAME VARCHAR(100) NOT NULL, AGE_VAL INTEGER NOT NULL, PRIMARY_ADDR_ID INTEGER);
CREATE TABLE T_ADDRESS (ID INTEGER PRIMARY KEY, PERSON_ID INTEGER NOT NULL, STREET VARCHAR(200) NOT NULL, CITY VARCHAR(100) NOT NULL);
